/* rsa2048 built on amu's native object route (JUN-708) against the committed kotoba-compiler/1 object. The native export
   takes each region's length after it: (signature 256 digest 32 workspace length 0) for the old (signature digest
   workspace length 0). Cases: the two signatures committed with the kernel (kotoba/app-catalog.sig and user-smoke.sig)
   with the digests their public-key operation recovers (both must verify), each with one digest byte or one signature
   bit changed, 40 random signatures (below the modulus, the modulus, above it, 0, 1 and n - 1), workspace lengths
   1283 (refused), 1284, 2048 and 4096, and a null signature, digest or workspace. Both objects start from the same
   random workspace bytes; answers, traps (through the #UD guard) and every workspace byte (the whole modular
   exponentiation result) are compared. The native object alone with a signature or digest region one byte short traps,
   and with longer regions (above the tier's 4096; the export narrows each to its old size) answers as before. */
#include "diff.h"
/* Calls with more than the five arguments guarded_call passes: the arguments go in ta[], guarded_call runs tramp, and
   tramp calls tf with all eight. A trap inside tf resumes at guarded_call's return as usual. */
typedef int64_t (*fn8)(int64_t, int64_t, int64_t, int64_t, int64_t, int64_t, int64_t, int64_t);
static void *tf; static int64_t ta[8];
static int64_t tramp(void) { return ((fn8)tf)(ta[0], ta[1], ta[2], ta[3], ta[4], ta[5], ta[6], ta[7]); }
__attribute__((unused)) static int64_t call8(void *f, int64_t a0, int64_t a1, int64_t a2, int64_t a3, int64_t a4, int64_t a5, int64_t a6, int64_t a7, int *trapped) {
  tf = f; ta[0] = a0; ta[1] = a1; ta[2] = a2; ta[3] = a3; ta[4] = a4; ta[5] = a5; ta[6] = a6; ta[7] = a7;
  int64_t r = guarded_call((void *)tramp, 0, 0, 0, 0, 0); *trapped = (int)guard_trapped; return r;
}
